    def storyboard(self, plan, screenplay, feedback=None):
        self.set_stage("storyboarding")
        board = self.structured(Storyboard, "Create a declarative visual storyboard. Reuse stable object IDs across scenes, map every narration block, attach forces/measurements, and use camera intent. Do not use raw Manim calls or arbitrary Python.", {"lesson_plan": plan.model_dump(), "screenplay": screenplay.model_dump(), "primitive_catalog": ["circle", "rectangle", "wheel", "bicycle", "arrow", "text", "equation", "vector"], "feedback": feedback})
        validate_storyboard(board, screenplay); self.store.write_json("storyboard", board); return board
    def criticize(self, plan, screenplay, board):
